) ON CONFLICT (tenant_id, key, locale, version) DO NOTHING;

INSERT INTO help_content (id, tenant_id, key, audience, locale, short_text, long_md, version, status)
VALUES (
  gen_random_uuid(),
  NULL,
  'admin.org_upload.page',
  'admin',
  'en',
  'Upload your own questions. You see a check first. Nothing is saved until you confirm.',
  $$## Upload questions

Use this page to add questions from a CSV or XLSX file.

- **Private.** The questions belong to your organisation only.
- **Check first.** You see how many rows are valid, wrong or duplicate before anything is saved.
- **Review next.** Saved questions start as In review. Check them on the question review screen before you invite candidates.
- **Withdraw.** You can withdraw a whole upload later from the list on this page.
$$,
  1,
  'active'
) ON CONFLICT (tenant_id, key, locale, version) DO NOTHING;

